<template>
  <section class="cinema-container">
    <header class="cinema-hero">
      <div><p class="eyebrow">LUNU CINEMA / TEA ROOM</p><h1>LuNu <em>Tea Room.</em></h1><p>Một căn phòng riêng để nghe nhạc, xem những video đã được lưu và thưởng thức media theo cách của bạn.</p></div><div class="cinema-badge">{{ videos.length }} VIDEO{{ videos.length === 1 ? '' : 'S' }}</div>
    </header>
    <div v-if="isAdmin" class="cinema-panel glass-panel">
      <div class="panel-heading"><div><span class="panel-kicker">VIDEO IMPORT PIPELINE</span><h2>Tìm video hoặc kênh YouTube</h2></div><span class="status-dot">● ONLINE</span></div>
      <div class="search-wrapper"><select v-model="searchMode" class="search-mode" aria-label="Kiểu tìm kiếm"><option value="video">Video</option><option value="channel">Kênh</option></select><label class="search-field"><span>⌕</span><input v-model.trim="searchQuery" @keyup.enter="handleSearch" type="search" :placeholder="searchMode === 'channel' ? 'Nhập tên kênh YouTube...' : 'Nhập tên video YouTube...'" :disabled="isSearching || isImporting" /></label><button class="action-btn" @click="handleSearch" :disabled="isSearching || isImporting || !searchQuery">{{ isSearching ? 'Đang tìm...' : 'Tìm kiếm' }} <span>→</span></button></div>
      <p v-if="message" class="status-message" :class="messageType" role="status">{{ message }}</p>
      <div v-if="selectedVideo" class="selected-panel"><div class="selected-heading"><div><span class="panel-kicker">SELECTED VIDEO</span><h3>Chỉnh sửa thông tin trước khi lưu</h3></div><button class="close-btn" @click="clearSelection">×</button></div><div class="selected-video"><img :src="thumbnail(selectedVideo)" :alt="selectedVideo.title" class="selected-thumb" /><div><strong>{{ selectedVideo.title }}</strong><span>{{ selectedVideo.uploader || 'YouTube' }}</span><small>youtube.com/watch?v={{ selectedVideo.id }}</small></div></div><form class="metadata-form" @submit.prevent="handleImport"><label><span>TÊN VIDEO</span><input v-model.trim="metadata.title" required maxlength="240" /></label><label><span>KÊNH / NGƯỜI ĐĂNG</span><input v-model.trim="metadata.uploader" required maxlength="160" /></label><label class="wide"><span>MÔ TẢ</span><textarea v-model.trim="metadata.description" maxlength="5000" rows="3" placeholder="Mô tả ngắn (không bắt buộc)"></textarea></label><div class="form-actions"><button type="button" class="cancel-btn" @click="clearSelection">Chọn video khác</button><button type="submit" class="action-btn" :disabled="isImporting || !metadata.title || !metadata.uploader">{{ isImporting ? importLabel : 'Tải video & lưu vào Cinema' }} <span>↗</span></button></div></form></div>
      <div v-if="!selectedVideo && searchResults.length" class="results-heading"><span>{{ searchResults.length }} kết quả</span><small>Chọn video muốn lưu</small></div><div v-if="!selectedVideo && searchResults.length" class="results-list"><article v-for="video in searchResults" :key="video.id" class="result-item"><img :src="thumbnail(video)" :alt="video.title" class="video-thumb" loading="lazy" /><div class="video-info"><h4 :title="video.title">{{ video.title }}</h4><p>{{ video.uploader || 'Không rõ kênh' }}</p></div><button class="select-btn" @click="selectVideo(video)">Chọn <span>→</span></button></article></div>
    </div>
    <div class="cinema-panel glass-panel library-panel"><div class="panel-heading"><div><span class="panel-kicker">CINEMA LIBRARY</span><h2>Kho video của bạn</h2></div><button class="refresh-btn" @click="loadVideos">↻ Làm mới</button></div><div v-if="isLoading" class="inline-state">Đang tải kho video...</div><div v-else-if="!videos.length" class="inline-state">Chưa có video nào. Hãy tìm và lưu video đầu tiên.</div><div v-else class="video-grid"><article v-for="video in videos" :key="video.id" class="cinema-card"><div class="video-frame"><video :src="video.url" :poster="video.cover || thumbnail(video)" controls preload="metadata"></video><span class="media-key">{{ video.media_key || 'VD' }}</span><button type="button" class="theater-trigger" @click="activeVideo = video">Xem trong phòng trà ↗</button></div><div class="card-copy"><h3 :title="video.title">{{ video.title }}</h3><p>{{ video.uploader || 'YouTube' }}</p><small>{{ video.created_at ? new Date(video.created_at).toLocaleDateString('vi-VN') : '' }}</small></div><button class="delete-btn" @click="handleDelete(video.id)">Xóa video & file Cloudinary</button></article></div></div>
    <Teleport to="body"><div v-if="activeVideo" class="theater-backdrop" @click.self="activeVideo = null"><section class="theater-room" role="dialog" aria-modal="true" :aria-label="`Đang xem ${activeVideo.title}`"><header><div><span class="panel-kicker">LUNU TEA ROOM / NOW WATCHING</span><h2>{{ activeVideo.title }}</h2><p>{{ activeVideo.uploader || 'YouTube' }} · {{ activeVideo.media_key || 'VIDEO' }}</p></div><button type="button" class="close-btn" @click="activeVideo = null">×</button></header><video :src="activeVideo.url" :poster="activeVideo.cover || thumbnail(activeVideo)" controls autoplay playsinline></video><p class="theater-description">{{ activeVideo.description || 'Thưởng thức video trong không gian riêng của LuNu.' }}</p></section></div></Teleport>
  </section>
</template>

<script setup>
import { computed, onBeforeUnmount, onMounted, reactive, ref } from 'vue';
import { addCinemaVideo, deleteCinemaVideo, getCinemaVideos, getImportJob, searchCinema } from '../services/api';
import { authState } from '../store/appState';

const searchQuery = ref(''); const searchMode = ref('video'); const searchResults = ref([]); const selectedVideo = ref(null); const activeVideo = ref(null); const videos = ref([]); const isSearching = ref(false); const isImporting = ref(false); const isLoading = ref(false); const message = ref(''); const messageType = ref(''); const importLabel = ref('Đang xử lý...'); let pollTimer = null;
const isAdmin = computed(() => authState.user?.role === 'admin');
const metadata = reactive({ title: '', uploader: '', cover: '', description: '' });
const thumbnail = (video) => video?.thumbnail || `https://i.ytimg.com/vi/${video?.id}/hqdefault.jpg`;
const loadVideos = async () => { isLoading.value = true; try { videos.value = await getCinemaVideos(); } catch (error) { message.value = error.message; messageType.value = 'error'; } finally { isLoading.value = false; } };
const clearSelection = () => { selectedVideo.value = null; metadata.title = ''; metadata.uploader = ''; metadata.cover = ''; metadata.description = ''; };
const selectVideo = (video) => { selectedVideo.value = video; metadata.title = video.title || ''; metadata.uploader = video.uploader || 'YouTube'; metadata.cover = thumbnail(video); metadata.description = ''; message.value = 'Bạn có thể chỉnh lại tên video và kênh trước khi tải.'; messageType.value = ''; };
const handleSearch = async () => { if (!searchQuery.value) return; isSearching.value = true; message.value = 'Đang tìm video tương tự trên YouTube...'; messageType.value = ''; searchResults.value = []; clearSelection(); try { const response = await searchCinema(searchQuery.value, searchMode.value); if (!response?.success) throw new Error(response?.message || 'Không tìm thấy video.'); searchResults.value = response.results || []; message.value = searchResults.value.length ? `Tìm thấy ${searchResults.value.length} video${searchMode.value === 'channel' ? ' từ kênh phù hợp' : ''}. Hãy chọn video muốn lưu.` : (response.message || 'Không có kết quả phù hợp.'); } catch (error) { message.value = error.message || 'Không thể tìm kiếm YouTube.'; messageType.value = 'error'; } finally { isSearching.value = false; } };
const pollImport = async (jobId) => { try { const response = await getImportJob(jobId); importLabel.value = response.message || 'Đang xử lý...'; if (response.status === 'completed') { message.value = `Đã lưu “${response.video?.title || metadata.title}” vào LuNu Cinema.`; messageType.value = 'success'; isImporting.value = false; clearSelection(); searchResults.value = []; searchQuery.value = ''; await loadVideos(); return; } if (response.status === 'failed') throw new Error(response.message || 'Tải video thất bại.'); pollTimer = window.setTimeout(() => pollImport(jobId), 2500); } catch (error) { isImporting.value = false; message.value = error.message || 'Không thể kiểm tra trạng thái tải video.'; messageType.value = 'error'; } };
const handleImport = async () => { if (!selectedVideo.value || !metadata.title || !metadata.uploader) return; isImporting.value = true; message.value = 'Đang gửi video lên Render...'; messageType.value = ''; importLabel.value = 'Đang xếp hàng...'; try { const response = await addCinemaVideo({ videoId: selectedVideo.value.id, title: metadata.title, uploader: metadata.uploader, cover: metadata.cover, description: metadata.description }); if (!response?.success || !response.job_id) throw new Error(response?.message || 'Backend không nhận được yêu cầu.'); message.value = 'Đã nhận. Đang tải video, upload Cloudinary và ghi Supabase...'; importLabel.value = 'Đang tải video...'; await pollImport(response.job_id); } catch (error) { isImporting.value = false; message.value = error.message || 'Không thể bắt đầu tải video.'; messageType.value = 'error'; } };
const handleDelete = async (id) => { if (!window.confirm('Xóa video này và file trên Cloudinary?')) return; try { await deleteCinemaVideo(id); if (activeVideo.value?.id === id) activeVideo.value = null; await loadVideos(); message.value = 'Đã xóa video và file Cloudinary.'; messageType.value = 'success'; } catch (error) { message.value = error.message; messageType.value = 'error'; } };
onMounted(() => { loadVideos(); }); onBeforeUnmount(() => { if (pollTimer) window.clearTimeout(pollTimer); });
</script>

<style scoped>
.cinema-container { max-width: 1180px; margin: 0 auto; padding: 18px 0 60px; }.cinema-hero { display:flex; align-items:flex-end; justify-content:space-between; gap:24px; padding:32px 0 34px; }.eyebrow,.panel-kicker { color:var(--gold); font:9px var(--font-mono); letter-spacing:1.8px; }.cinema-hero h1 { margin-top:12px; font:500 clamp(40px,5vw,64px)/.95 var(--font-display); letter-spacing:-2px; }.cinema-hero h1 em { color:var(--gold); font-style:italic; }.cinema-hero p:last-child { max-width:560px; margin-top:15px; color:var(--text-sub); font-size:12px; line-height:1.6; }.cinema-badge { padding:10px 12px; border:1px solid rgba(245,185,122,.25); border-radius:10px; color:var(--gold); font:9px var(--font-mono); white-space:nowrap; }.cinema-panel { margin-bottom:18px; padding:clamp(18px,3vw,28px); border-radius:18px; }.panel-heading,.selected-heading,.results-heading { display:flex; align-items:center; justify-content:space-between; gap:14px; }.panel-heading h2 { margin-top:7px; color:var(--text-main); font:500 23px var(--font-display); }.status-dot { color:var(--mint); font:8px var(--font-mono); letter-spacing:1px; }.search-wrapper { display:flex; gap:9px; margin-top:18px; }.search-mode { width:105px; padding:12px 10px; border:1px solid var(--hairline); border-radius:10px; outline:0; background:rgba(3,5,9,.34); color:var(--text-main); font-size:10px; }.search-field { display:flex; align-items:center; flex:1; gap:10px; padding:12px 13px; border:1px solid var(--hairline); border-radius:10px; background:rgba(3,5,9,.34); }.search-field:focus-within { border-color:rgba(245,185,122,.6); }.search-field span { color:var(--gold); font-size:18px; }.search-field input { width:100%; border:0; outline:0; background:transparent; color:var(--text-main); font-size:11px; }.action-btn,.select-btn,.cancel-btn,.refresh-btn,.delete-btn { border-radius:9px; padding:10px 12px; cursor:pointer; font-size:10px; font-weight:800; }.action-btn { border:0; background:linear-gradient(135deg,var(--gold-bright),var(--gold)); color:#171218; }.action-btn:disabled { opacity:.55; cursor:progress; }.action-btn span,.select-btn span { margin-left:8px; font-size:14px; }.status-message { margin:14px 0 0; color:var(--text-sub); font-size:10px; line-height:1.5; }.status-message.success { color:var(--mint); }.status-message.error { color:var(--crimson); }.selected-panel { margin-top:16px; padding:18px; border:1px solid rgba(245,185,122,.28); border-radius:13px; background:linear-gradient(110deg,rgba(245,185,122,.08),rgba(155,140,255,.05)); }.selected-heading h3 { margin-top:6px; font:500 18px var(--font-display); }.close-btn { width:29px; height:29px; border:1px solid var(--hairline); border-radius:8px; background:transparent; color:var(--text-sub); cursor:pointer; font-size:18px; }.selected-video { display:flex; align-items:center; gap:12px; margin:18px 0; }.selected-thumb { width:110px; height:62px; border-radius:9px; object-fit:cover; }.selected-video div { display:flex; flex-direction:column; min-width:0; }.selected-video strong { overflow:hidden; color:var(--text-main); text-overflow:ellipsis; white-space:nowrap; font-size:11px; }.selected-video span,.selected-video small { margin-top:5px; color:var(--text-sub); font-size:9px; }.selected-video small { color:var(--text-faint); font-family:var(--font-mono); }.metadata-form { display:grid; grid-template-columns:1fr 1fr; gap:10px; }.metadata-form label { display:grid; gap:6px; }.metadata-form label span { color:var(--text-faint); font:8px var(--font-mono); letter-spacing:1px; }.metadata-form input,.metadata-form textarea { width:100%; box-sizing:border-box; padding:11px 12px; border:1px solid var(--hairline); border-radius:9px; outline:0; background:rgba(3,5,9,.3); color:var(--text-main); font:11px var(--font-sans); resize:vertical; }.metadata-form input:focus,.metadata-form textarea:focus { border-color:var(--gold); }.metadata-form .wide,.form-actions { grid-column:1/-1; }.form-actions { display:flex; justify-content:flex-end; gap:8px; margin-top:7px; }.cancel-btn,.refresh-btn { border:1px solid var(--hairline); background:transparent; color:var(--text-sub); }.results-heading { margin-top:18px; color:var(--text-main); font-size:11px; }.results-heading small { color:var(--text-faint); font-size:9px; }.results-list { display:flex; flex-direction:column; gap:6px; max-height:420px; margin-top:9px; overflow:auto; }.result-item { display:flex; align-items:center; gap:12px; padding:9px; border:1px solid transparent; border-radius:10px; background:rgba(3,5,9,.23); }.result-item:hover { border-color:var(--hairline); }.video-thumb { width:100px; height:56px; border-radius:7px; object-fit:cover; }.video-info { flex:1; min-width:0; }.video-info h4,.video-info p { overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }.video-info h4 { color:var(--text-main); font-size:11px; }.video-info p { margin-top:5px; color:var(--text-sub); font-size:9px; }.select-btn { border:1px solid rgba(245,185,122,.32); background:rgba(245,185,122,.08); color:var(--gold); }.inline-state { padding:40px 20px; color:var(--text-sub); text-align:center; font-size:11px; }.video-grid { display:grid; grid-template-columns:repeat(auto-fill,minmax(250px,1fr)); gap:14px; }.cinema-card { overflow:hidden; border:1px solid var(--hairline-soft); border-radius:13px; background:rgba(3,5,9,.3); }.video-frame { position:relative; aspect-ratio:16/9; background:#06070b; }.video-frame video { width:100%; height:100%; object-fit:cover; }.theater-trigger { position:absolute; right:8px; bottom:8px; border:1px solid rgba(255,255,255,.2); border-radius:7px; padding:6px 8px; background:rgba(3,5,9,.72); color:#fff; cursor:pointer; font-size:9px; opacity:0; transition:.2s ease; }.video-frame:hover .theater-trigger { opacity:1; }.media-key { position:absolute; top:8px; left:8px; padding:5px 7px; border-radius:6px; background:rgba(3,5,9,.75); color:var(--gold); font:8px var(--font-mono); }.card-copy { padding:12px 12px 0; }.card-copy h3 { overflow:hidden; color:var(--text-main); text-overflow:ellipsis; white-space:nowrap; font-size:12px; }.card-copy p { margin-top:6px; color:var(--text-sub); font-size:10px; }.card-copy small { display:block; margin-top:5px; color:var(--text-faint); font:9px var(--font-mono); }.cinema-card .delete-btn { margin:12px; border:1px solid rgba(255,109,125,.22); background:transparent; color:var(--crimson); }.cinema-card .delete-btn:hover { background:rgba(255,109,125,.1); }.theater-backdrop { position:fixed; inset:0; z-index:420; display:grid; place-items:center; padding:20px; background:rgba(2,4,8,.82); backdrop-filter:blur(12px); }.theater-room { width:min(980px, 100%); max-height:calc(100vh - 40px); overflow:auto; padding:20px; border:1px solid var(--hairline); border-radius:18px; background:#11151f; box-shadow:0 30px 100px rgba(0,0,0,.55); }.theater-room header { display:flex; align-items:flex-start; justify-content:space-between; gap:12px; margin-bottom:14px; }.theater-room h2 { margin-top:6px; color:var(--text-main); font:500 24px var(--font-display); }.theater-room header p { margin-top:5px; color:var(--text-sub); font-size:10px; }.close-btn { width:30px; height:30px; border:1px solid var(--hairline); border-radius:8px; background:transparent; color:var(--text-main); cursor:pointer; font-size:18px; }.theater-room > video { display:block; width:100%; max-height:68vh; border-radius:10px; background:#05060a; }.theater-description { margin-top:12px; color:var(--text-sub); font-size:11px; line-height:1.5; }.search-wrapper select { appearance:auto; }@media(max-width:700px){.cinema-hero{align-items:flex-start;flex-direction:column}.search-wrapper{display:grid;grid-template-columns:1fr}.metadata-form{grid-template-columns:1fr}.metadata-form .wide,.form-actions{grid-column:1}.form-actions{flex-wrap:wrap}.form-actions>*{flex:1}.result-item{align-items:flex-start;flex-wrap:wrap}.video-info{width:calc(100% - 115px)}.select-btn{width:100%}}
</style>
